import logging
import re

from ta_moler.device.nokia_proxy_pc import NokiaProxyPc
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name

ACTION_TO_CHANGE_STATE = {
    "action": [
        "_execute_command_to_change_state"
    ]
}


@call_base_class_method_with_same_name
class RtgController(NokiaProxyPc):
    r"""
    RTG controller device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
          RTG_CONSOLE:
            DEVICE_CLASS: ta_moler.device.rtg_console.RtgController
            CONNECTION_HOPS:
              UNIX_LOCAL:
                PROXY_PC:
                  execute_command: ssh
                  command_params:
                    host: host.pl
                    login: rtg
                    password: 'asdf'
                    expected_prompt: .*>
                    timeout: 30
              PROXY_PC:
                LINUX:
                  command_params:
                    host: 10.60.0.10
              LINUX:
                PROXY_PC:
                  command_params:
                    expected_prompt: .*>
    - without PROXY_PC:
      RTG_CONSOLE:
       DEVICE_CLASS: ta_moler.device.rtg_console.RtgController
       CONNECTION_HOPS:
         UNIX_LOCAL:
           LINUX:
             execute_command: telnet # default value
             command_params:
               host: tty_server_host
               port: tty_port
    """

    linux = "LINUX"
    argon = "ARGON"
    uesim = "UESIM"
    dsps = ["DSP1", "DSP2", "DSP3", "DSP4", "DSP5", "DSP6", "DSP7", "DSP8"]

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else RtgController.linux
        super(RtgController, self).__init__(sm_params=sm_params, name=name, io_connection=io_connection,
                                            io_type=io_type, variant=variant,
                                            io_constructor_kwargs=io_constructor_kwargs, initial_state=initial_state,
                                            lazy_cmds_events=lazy_cmds_events)
        self.logger = logging.getLogger('moler.rtg_controller')

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        config = {
            RtgController.connection_hops: {
                RtgController.proxy_pc: {  # from
                    RtgController.linux: {  # to
                        "execute_command": "ssh",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'toor4nsn@fzm-lsp-k2:.*#',
                            "login": "rtg",
                            "password": "rtg",
                            "allowed_newline_after_prompt": True,
                        },
                        "required_command_params": [
                            "host",
                        ]
                    },
                },
                RtgController.linux: {  # from
                    RtgController.proxy_pc: {  # to
                        "execute_command": "exit",  # using command
                        "command_params": {  # with parameters
                        },
                        "required_command_params": [
                            "expected_prompt"
                        ]
                    },
                    RtgController.argon: {  # to
                        "execute_command": "reboot_argon",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'ARGON\s*#'
                        },
                        "required_command_params": []
                    },
                    RtgController.uesim: {  # to
                        "execute_command": "telnet",  # using command
                        "command_params": {  # with parameters
                            # need to change prompt to one agreed with rtg team
                            "expected_prompt": r'Enter command.*',
                            "port": 8498,
                            "host": 0,
                            "set_timeout": False,
                            "allowed_newline_after_prompt": True,
                        },
                        "required_command_params": []
                    },
                },
                RtgController.argon: {
                    RtgController.linux: {  # to
                        "execute_command": "boot",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'toor4nsn@fzm-lsp-k2:.*#',
                        },
                        "required_command_params": []
                    },
                },
                RtgController.uesim: {
                    RtgController.linux: {
                        "execute_command": "exit_uesim",  # using command
                        "command_params":
                            {  # with parameters
                                "expected_prompt": r'toor4nsn@fzm-lsp-k2:.*#'
                            },
                        "required_command_params": []
                    }
                }
            }
        }
        self.__update_dsp_list_configuration(config)
        return config

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        transitions = {
            RtgController.linux: {
                RtgController.proxy_pc: ACTION_TO_CHANGE_STATE,
                RtgController.argon: ACTION_TO_CHANGE_STATE,
                RtgController.uesim: ACTION_TO_CHANGE_STATE,
            },
            RtgController.proxy_pc: {
                RtgController.linux: ACTION_TO_CHANGE_STATE,
                RtgController.unix_local: ACTION_TO_CHANGE_STATE
            },
            RtgController.argon: {
                RtgController.linux: ACTION_TO_CHANGE_STATE
            },
            RtgController.uesim: {
                RtgController.linux: ACTION_TO_CHANGE_STATE
            },
            RtgController.unix_local: {
                RtgController.proxy_pc: ACTION_TO_CHANGE_STATE
            },
        }
        self.__update_transitions_for_dsps(transitions)
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        state_prompts = {
            RtgController.linux:
                self._configurations[RtgController.connection_hops][RtgController.proxy_pc][RtgController.linux][
                    "command_params"]["expected_prompt"],
            RtgController.argon:
                self._configurations[RtgController.connection_hops][RtgController.linux][RtgController.argon][
                    "command_params"]["expected_prompt"],
            RtgController.uesim:
                self._configurations[RtgController.connection_hops][RtgController.linux][RtgController.uesim][
                    "command_params"]["expected_prompt"],
            RtgController.proxy_pc:
                self._configurations[RtgController.connection_hops][RtgController.linux][RtgController.proxy_pc][
                    "command_params"]["expected_prompt"],
        }
        self.__update_state_prompts(state_prompts)
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        state_prompts = {
            RtgController.linux:
                self._configurations[RtgController.connection_hops][RtgController.unix_local][RtgController.linux][
                    "command_params"]["expected_prompt"],
            RtgController.argon:
                self._configurations[RtgController.connection_hops][RtgController.linux][RtgController.argon][
                    "command_params"]["expected_prompt"],
            RtgController.uesim:
                self._configurations[RtgController.connection_hops][RtgController.linux][RtgController.uesim][
                    "command_params"]["expected_prompt"],
        }
        self.__update_state_prompts(state_prompts)
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        state_hops = {
            RtgController.not_connected: {
                RtgController.linux: RtgController.unix_local,
                RtgController.argon: RtgController.unix_local,
                RtgController.uesim: RtgController.unix_local,
            },
            RtgController.linux: {
                RtgController.not_connected: RtgController.proxy_pc,
                RtgController.unix_local: RtgController.proxy_pc,
                RtgController.unix_local_root: RtgController.proxy_pc,
            },
            RtgController.argon: {
                RtgController.unix_local: RtgController.linux,
                RtgController.unix_local_root: RtgController.linux,
                RtgController.proxy_pc: RtgController.linux,
                RtgController.not_connected: RtgController.linux,
                RtgController.uesim: RtgController.linux,
            },
            RtgController.uesim: {
                RtgController.unix_local: RtgController.linux,
                RtgController.unix_local_root: RtgController.linux,
                RtgController.proxy_pc: RtgController.linux,
                RtgController.not_connected: RtgController.linux,
                RtgController.argon: RtgController.linux,
            },
            RtgController.unix_local: {
                RtgController.linux: RtgController.proxy_pc,
                RtgController.argon: RtgController.proxy_pc,
                RtgController.uesim: RtgController.proxy_pc,
            },
            RtgController.proxy_pc: {
                RtgController.argon: RtgController.linux,
                RtgController.unix_local_root: RtgController.unix_local,
                RtgController.uesim: RtgController.linux,
            },
            RtgController.unix_local_root: {
                RtgController.argon: RtgController.unix_local,
                RtgController.uesim: RtgController.unix_local,
                RtgController.linux: RtgController.unix_local,
            },
        }
        self.__def_add_next_hop_for_dsp_list(state_hops, is_proxy_connection=True)
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(RtgController, self)._get_packages_for_state(state, observer)

        if not available:
            if state == RtgController.linux:
                available = {RtgController.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix',
                                                  'ta_moler.cmd.shared.enblinux',
                                                  'ta_moler.cmd.fzmconsole.linux', 'ta_moler.cmd.rtg_ctrl.linux'],
                             RtgController.events: ['moler.events.shared', 'moler.events.unix',
                                                    'ta_moler.events.fzmconsole', 'ta_moler.events.rtg_ctrl']}
            elif state == RtgController.argon:
                available = {RtgController.cmds: ['ta_moler.cmd.shared.argon', 'ta_moler.cmd.fzmconsole.argon'],
                             RtgController.events: ['moler.events.shared', 'moler.events.unix',
                                                    'ta_moler.events.fzmconsole']}
            elif re.match(r"DSP\d", state):
                available = self.__get_dsp_packages()
            elif state == RtgController.uesim:
                available = {RtgController.cmds: ['ta_moler.cmd.rtg_ctrl.uesim'],
                             RtgController.events: ['moler.events.shared']}
            if available:
                return available[observer]

        return available

    def __update_state_prompts(self, state_prompts):
        for dsp in RtgController.dsps:
            state_prompts[dsp] = self._configurations[RtgController.connection_hops][RtgController.linux][dsp][
                "command_params"]["expected_prompt"]

    @staticmethod
    def __def_add_next_hop_for_dsp_list(state_hops, is_proxy_connection):
        dsp_elements = {
            RtgController.unix_local: RtgController.linux,
            RtgController.unix_local_root: RtgController.linux,
            RtgController.not_connected: RtgController.linux,
            RtgController.argon: RtgController.linux,
            RtgController.uesim: RtgController.linux
        }

        if is_proxy_connection:
            dsp_elements[RtgController.proxy_pc] = RtgController.linux

        dsp_number = 0
        for dsp in RtgController.dsps:
            if is_proxy_connection:
                state_hops[RtgController.unix_local][dsp] = RtgController.proxy_pc
                state_hops[RtgController.proxy_pc][dsp] = RtgController.linux
            else:
                state_hops[RtgController.unix_local][dsp] = RtgController.linux
            state_hops[RtgController.not_connected][dsp] = RtgController.unix_local
            state_hops[RtgController.unix_local_root][dsp] = RtgController.unix_local
            state_hops[RtgController.uesim][dsp] = RtgController.linux
            state_hops[RtgController.argon][dsp] = RtgController.linux
            state_hops[dsp] = {}
            state_hops[dsp].update(dsp_elements)
            rest_dsps = list(RtgController.dsps)
            rest_dsps.pop(dsp_number)
            dsp_number += 1
            for other_dsp in rest_dsps:
                state_hops[dsp][other_dsp] = RtgController.linux

    @staticmethod
    def __update_transitions_for_dsps(transitions):
        for dsp in RtgController.dsps:
            transitions[RtgController.linux][dsp] = ACTION_TO_CHANGE_STATE
            transitions[dsp] = {RtgController.linux: ACTION_TO_CHANGE_STATE}

    @staticmethod
    def __get_dsp_packages():
        return {RtgController.cmds: ['ta_moler.cmd.rtg_ctrl.dsp'],
                RtgController.events: ['moler.events.shared']}

    @staticmethod
    def __generate_change_from_dsp_sm_configuration(dsp_number):
        return {
            RtgController.linux: {
                "execute_command": "exit_mmi",  # using command
                "command_params":
                    {  # with parameters
                        "prompt": RtgController.__generate_dsp_prompt(dsp_number),
                        "expected_prompt": r'toor4nsn@fzm-lsp-k2:.*#\s*',
                    },
                "required_command_params": []
            }
        }

    def __generate_change_to_dsp_sm_configuration(self, dsp_number):
        return {  # to
            "execute_command": "mmi",
            "command_params": {
                "expected_prompt": self.__generate_dsp_prompt(dsp_number),
                "dsp_number": dsp_number,
            },
            "required_command_params": []
        }

    def __update_dsp_list_configuration(self, config):
        dsp_number = 1
        for dsp in RtgController.dsps:
            config[RtgController.connection_hops][RtgController.linux][dsp] = \
                self.__generate_change_to_dsp_sm_configuration(dsp_number=dsp_number)
            config[RtgController.connection_hops][dsp] = \
                self.__generate_change_from_dsp_sm_configuration(dsp_number=dsp_number)
            dsp_number += 1

    @staticmethod
    def __generate_dsp_prompt(dsp_number):
        return rf"Core\s*(?:123\.)?{dsp_number}\s*>"

    def _trim_config_dicts(self, default_sm_configurations, transitions, state_hops):
        """
        Remove required state (mainly PROXY_PC) from State Machine configuration if necessary.

        :param default_sm_configurations: default State Machine configuration.
        :param transitions: transitions between states.
        :param state_hops: non direct transitions between states.
        :return: trimmed State Machine configuration (tuple with new values of passed arguments).
        """
        (default_sm_configurations, transitions, state_hops) = super(RtgController, self)._trim_config_dicts(
            default_sm_configurations=default_sm_configurations,
            transitions=transitions,
            state_hops=state_hops
        )
        if not self._use_proxy_pc:
            default_sm_configurations[RtgController.connection_hops][RtgController.unix_local][RtgController.linux]["command_params"].pop("allowed_newline_after_prompt")
            default_sm_configurations[RtgController.connection_hops][RtgController.unix_local][RtgController.linux]["required_command_params"].append('port')
            default_sm_configurations[RtgController.connection_hops][RtgController.linux][RtgController.unix_local]["execute_command"] = 'exit_telnet'
        return (default_sm_configurations, transitions, state_hops)
